package com.northstar.crm.security;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Instant;import java.util.*;@Component public class ScopeTokenService {private final byte[] key;public ScopeTokenService(@Value("${app.session-signing-key}")String key){this.key=key.getBytes(StandardCharsets.UTF_8);}public String mint(UUID org,String purpose){var value=org+"|"+purpose+"|"+Instant.now().plusSeconds(60).getEpochSecond();return Base64.getUrlEncoder().withoutPadding().encodeToString(value.getBytes(StandardCharsets.UTF_8))+"."+sign(value);}public UUID verify(String token,String purpose){try{var parts=token.split("\\.");var value=new String(Base64.getUrlDecoder().decode(parts[0]),StandardCharsets.UTF_8);if(parts.length!=2||!MessageDigest.isEqual(sign(value).getBytes(StandardCharsets.US_ASCII),parts[1].getBytes(StandardCharsets.US_ASCII)))throw new SecurityException();var p=value.split("\\|");if(p.length!=3||!p[1].equals(purpose)||Instant.now().getEpochSecond()>Long.parseLong(p[2]))throw new SecurityException();return UUID.fromString(p[0]);}catch(Exception e){throw new SecurityException("Invalid decision scope token");}}private String sign(String v){try{var mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(key,"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
